# filename: test_orchestrator.py

from pathlib import Path

import tokenomics_logger
from cost_summary import log_query_cost
from orchestrator import build_orchestrator


# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: test_orchestrator.py

test_questions = [
    (
        "How many projects currently have status Active, and what are their names?",
        "sql",
        {"sql"},
    ),
    (
        "For the Supply Chain Planning Assessment, what is the status of the invoices and how much?",
        "sql",
        {"sql"},
    ),
    (
        "What is our onboarding process?",
        "retrieval",
        {"retrieval"},
    ),
    (
        "According to the remote-work policy, what are employees' core hours "
        "and the annual home-office equipment stipend?",
        "retrieval",
        {"retrieval"},
    ),
    (
        "What is the budget for Northstar Outfitters' Customer Insights Platform, "
        "and explain what discovery outputs and execution safeguards the migration "
        "playbook recommends if the project includes data migration? Cite both sources.",
        "both",
        {"sql", "retrieval"},
    ),
    (
        "What is the budget and status of Blue Oak Foods' Supply Chain Planning "
        "Assessment, and describe how the retail supply-chain case study's approach "
        "and reported results provide context? Cite both sources and do not imply "
        "the case study describes Blue Oak's engagement.",
        "both",
        {"sql", "retrieval"},
    ),
    (
        "Delete all records from the projects table.",
        "blocked",
        set(),
    ),
    (
        "Explain what jersey number Lamar Jackson wears according to our records.",
        "retrieval",
        {"retrieval"},
    ),
]



def validate_result(result, expected_route, expected_agents):
    issues = []

    actual_route = result.get("route")
    answer = result.get("final_answer") or ""

    if actual_route != expected_route:
        issues.append(
            f"Expected route {expected_route!r}; got {actual_route!r}"
        )

    if not answer.strip():
        issues.append("Answer is empty")

    if "sql" in expected_agents:
        if not (result.get("sql_result") or {}).get("success"):
            issues.append("SQL agent did not return success")

    if "retrieval" in expected_agents:
        if not (result.get("retrieval_result") or {}).get("success"):
            issues.append("Retrieval agent did not return success")

    return "PASS" if not issues else "FAIL", issues


def main():
    orchestrator = build_orchestrator()
    report_path = Path(__file__).with_name("orchestrator_test_results3.txt")
    report_sections = []

    for question, expected_route, expected_agents in test_questions:
        print(f"\n{'=' * 60}\nQ: {question}")

        try:
            result = tokenomics_logger.run_traced_query(orchestrator, question)

            sql_result = result.get("sql_result")
            retrieval_result = result.get("retrieval_result")
            sql_tokens = (sql_result or {}).get("metadata", {}).get(
                "token_usage", {}
            )
            retrieval_tokens = (retrieval_result or {}).get("metadata", {}).get(
                "token_usage", {}
            )

            breakdown = log_query_cost(question, result)
            validation, issues = validate_result(
                result, expected_route, expected_agents
            )

            route = result.get("route")
            answer = result.get("final_answer") or ""
            tokens = result.get("token_usage") or {}

            print(breakdown)
            print(f"Route: {route}")
            print(f"Answer: {answer}")
            print(f"Tokens: {tokens}")
            print(f"Validation: {validation}")
            if issues:
                print(f"Validation issues: {issues}")

            report_sections.append(
                "\n".join(
                    [
                        "=" * 60,
                        f"Question: {question}",
                        f"Route: {route}",
                        f"Answer: {answer}",
                        f"Validation status: {validation}",
                        f"Validation details: {issues or 'Passed'}",
                        f"Cost breakdown: {breakdown}",
                        f"Synthesis tokens: {tokens}",
                        f"SQL agent tokens: {sql_tokens}",
                        f"Retrieval agent tokens: {retrieval_tokens}",
                    ]
                )
            )

        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"
            print(f"Validation: FAIL")
            print(f"Error: {error}")

            report_sections.append(
                "\n".join(
                    [
                        "=" * 60,
                        f"Question: {question}",
                        "Route: ERROR",
                        "Answer: ",
                        "Validation status: FAIL",
                        f"Validation details: {error}",
                    ]
                )
            )

    report_path.write_text(
        "\n\n".join(report_sections) + "\n",
        encoding="utf-8",
    )
    print(f"\nTest report saved to: {report_path}")


if __name__ == "__main__":
    main()
